LOCK TABLES `licoes` WRITE;
/*!40000 ALTER TABLE `licoes` DISABLE KEYS */;
INSERT INTO `licoes` VALUES (1,1,1,'Introdução - Primeiros Passos em Java','Java tem uma sintaxe clara e estruturada. Para exibir mensagens e textos na tela do computador, usamos a instrução System.out.println().\n\nO computador precisa de instruções precisas para funcionar. Em Java, o comando println envia uma linha inteira de saída para o terminal.\n\nPratique com repetição: todo texto precisa estar dentro dos parênteses da instrução!','System.out.println(\"Olá, Mundo!\");','2026-10-08 16:05:50'),(2,1,2,'Introdução - A Regra das Aspas Duplas','Na programação Java, as aspas duplas são obrigatórias para textos. Quando colocamos caracteres entre \" \", o Java reconhece como uma String de texto.\n\nSe esquecermos as aspas em uma palavra ou frase, o compilador do Java gerará um erro e não conseguirá entender a instrução.\n\nLembre-se da regra de ouro: abra aspas duplas antes do texto e feche aspas duplas logo após!','System.out.println(\"Level Up\");','2026-10-08 16:05:50'),(3,1,3,'Introdução - Maiúsculas e Minúsculas','Java é uma linguagem Case-Sensitive. Isso significa que letras maiúsculas e minúsculas fazem total diferença para o computador!\n\nA palavra System começa obrigatoriamente com \'S\' maiúsculo. Se você escrever system ou SYSTEM, o Java não reconhecerá a classe.\n\nJá a instrução println é toda em minúsculas. Preste sempre muita atenção nas maiúsculas ao escrever seu código!','System.out.println(\"Atenção às maiúsculas!\");','2026-10-08 16:05:50'),(4,1,4,'Introdução - Parênteses e Ponto e Vírgula','Em Java, o conteúdo a ser exibido fica sempre dentro dos parênteses ( ).\n\nAlém disso, toda instrução em Java precisa terminar obrigatoriamente com o caractere ponto e vírgula (;).\n\nO ponto e vírgula indica ao computador onde o comando terminou. A fórmula completa é: System.out.println(\"Texto\");','System.out.println(\"Ponto e vírgula obrigatório!\");','2026-10-08 16:05:50'),(5,1,5,'Introdução - Desafio IDE: Olá Mundo','Chegou a hora de juntar tudo o que você aprendeu com repetição e colocar as mãos no código real!\n\nNeste desafio prático no estilo Codédex, você usará o editor de código e o terminal OpenJDK para programar seu primeiro Hello World.\n\nEscreva a instrução para exibir Olá Mundo na tela e execute o programa no terminal!','','2026-10-08 16:05:50'),(6,2,1,'Variáveis - O Tipo Inteiro (int)','Na programação, variáveis são como caixas na memória do computador onde guardamos informações para usar mais tarde.\n\nO tipo int (inteiro) serve para armazenar números inteiros, ou seja, números sem casas decimais (como 10, 42, -5 e 0).\n\nPara criar uma variável inteira, informamos o tipo int, o nome da variável, o sinal de igual (=) e o valor finalizado com ponto e vírgula (;).\n\nPara exibir o valor guardado na variável, passamos seu nome diretamente em System.out.println(pontos); sem aspas!','int pontos = 100;\nSystem.out.println(pontos);','2026-10-08 16:05:50'),(7,2,2,'Variáveis - Textos e a Classe String','Enquanto o tipo int guarda números inteiros, palavras e textos são representados em Java pelo tipo String.\n\nEm Java, a palavra String começa obrigatoriamente com \'S\' maiúsculo, pois tecnicamente ela é uma classe nativa da linguagem.\n\nO conteúdo de uma String deve ficar sempre delimitado por aspas duplas (\"...\"). Por exemplo: String jogador = \"Gabriel\";\n\nAssim como os números inteiros, para exibir a variável no console basta passar seu nome sem aspas para o comando de impressão.','String heroi = \"Link\";\nSystem.out.println(heroi);','2026-10-08 16:05:50'),(8,2,3,'Variáveis - Concatenação de Textos (+)','Na programação, concatenar significa juntar duas ou mais sequências de texto em uma só.\n\nEm Java, o símbolo + realiza a concatenação de textos quando pelo menos um dos valores for uma String!\n\nPodemos combinar um texto fixo com uma variável: System.out.println(\"Olá, \" + nome);\n\nTambém podemos juntar textos com variáveis numéricas. Preste sempre atenção nos espaços dentro das aspas para não colar as palavras!','String curso = \"Java\";\nint ano = 2026;\nSystem.out.println(\"Estudando \" + curso + \" em \" + ano);','2026-10-08 16:05:50'),(9,2,4,'Variáveis - Reatribuição e Atualização','O nome \'variável\' existe justamente porque seu valor pode variar ao longo da execução do programa!\n\nPara atualizar o valor de uma variável que já existe, NÃO devemos repetir o tipo (int ou String). Apenas usamos seu nome e o novo valor.\n\nSe você repetir o tipo (ex: int vidas = 2; novamente), o compilador acusará um erro de variável já declarada no mesmo bloco.\n\nO programa executa de cima para baixo. Portanto, a variável terá o valor da sua atribuição mais recente.','int moedas = 10;\nmoedas = 25;\nSystem.out.println(moedas);','2026-10-08 16:05:50'),(10,2,5,'Variáveis - Desafio IDE: Declarando Variáveis','Chegou a hora de colocar o conhecimento em prática no editor de código real!\n\nNeste desafio prático no estilo Codédex, você declarará uma variável inteira e exibirá seu valor no terminal.\n\nEscreva a instrução para declarar a variável e execute o programa para ver o resultado!','','2026-10-08 16:05:50'),(11,3,1,'Variáveis Parte 2 - Números Decimais (double)','No mundo real, nem todos os números são inteiros. Preços de produtos, alturas, pesos e médias escolares possuem casas decimais.\n\nEm Java, o tipo primitivo padrão para guardar números com casas decimais é o double.\n\nAtenção à regra fundamental de sintaxe: em Java, usamos sempre o PONTO (.) e nunca a vírgula para separar as casas decimais (ex: double preco = 19.90;).\n\nSe usarmos vírgula em um número decimal no código, o compilador do Java acusará um erro de sintaxe!','double altura = 1.75;\ndouble preco = 29.99;\nSystem.out.println(preco);','2026-10-08 16:05:50'),(12,3,2,'Variáveis Parte 2 - Lógica com boolean','Muitas vezes um programa precisa responder perguntas de Sim ou Não: O usuário está online? A porta está aberta? O aluno foi aprovado?\n\nPara armazenar valores lógicos em Java, utilizamos o tipo primitivo boolean.\n\nUma variável boolean aceita exclusivamente um de dois valores possíveis: true (verdadeiro) ou false (falso).\n\nEsses valores são palavras reservadas da linguagem Java: são escritos sempre em letras minúsculas e NUNCA levam aspas!','boolean aprovado = true;\nboolean chovendo = false;\nSystem.out.println(aprovado);','2026-10-08 16:05:50'),(13,3,3,'Variáveis Parte 2 - Caracteres Únicos (char)','Enquanto o tipo String armazena palavras e frases inteiras usando aspas duplas (\"...\"), o Java possui um tipo especial para um único caractere: o char.\n\nUma variável do tipo char armazena exatamente uma única letra, símbolo ou dígito (como \'A\', \'B\', \'$\' ou \'7\').\n\nA regra de ouro do tipo char é o uso obrigatório de ASPAS SIMPLES (\' \') ao redor do caractere!\n\nLembre-se: aspas simples (\'A\') são para char (um só caractere), e aspas duplas (\"Texto\") são para String!','char rank = \'S\';\nchar inicial = \'G\';\nSystem.out.println(rank);','2026-10-08 16:05:50'),(14,3,4,'Variáveis Parte 2 - Constantes com final','Existem valores que nunca devem mudar durante toda a execução de um programa, como o número Pi (3.14159) ou o limite máximo de jogadores.\n\nEm Java, usamos a palavra-chave final antes do tipo da variável para transformá-la em uma constante (um valor fixo e imutável).\n\nSe qualquer linha do código tentar alterar o valor de uma variável marcada com final, o compilador bloqueará a ação com um erro!\n\nPor convenção entre programadores Java, costumamos escrever o nome de constantes em LETRAS MAIÚSCULAS (ex: final int MAX_VIDAS = 3;).','final double PI = 3.14;\nfinal int MAX_NIVEL = 99;\nSystem.out.println(MAX_NIVEL);','2026-10-08 16:05:50'),(15,3,5,'Variáveis Parte 2 - Desafio IDE: Tipos de Dados','Chegou a hora de colocar o conhecimento sobre novos tipos de variáveis em prática no editor de código real!\n\nNeste desafio prático no estilo Codédex, você declarará uma variável decimal (double) e exibirá seu valor no terminal.\n\nEscreva a instrução no editor e clique em Executar para concluir a Seção 3!','','2026-10-08 16:05:50'),(16,4,1,'Operadores Parte 1 - Adição (+) e Subtração (-)','Os computadores são calculadoras extremamente rápidas! Em Java, usamos os operadores aritméticos para realizar cálculos matemáticos.\n\nO operador + soma dois valores numéricos, enquanto o operador - realiza a subtração.\n\nPodemos fazer a conta diretamente dentro do println ou guardar o resultado dentro de uma variável: int total = 10 + 5;\n\nLembre-se: quando ambos os lados do + são números (int ou double), o Java realiza a SOMA matemática!','int saldo = 100 - 30;\nint bonus = saldo + 20;\nSystem.out.println(bonus);','2026-10-08 16:05:50'),(17,4,2,'Operadores Parte 1 - Multiplicação (*) e Divisão (/)','Na programação Java, a multiplicação NÃO usa a letra \'x\'. Usamos sempre o símbolo asterisco (*).\n\nJá para a divisão, utilizamos a barra normal (/). Por exemplo: int metade = 20 / 2;\n\nAtenção a um detalhe importante do Java: quando dividimos dois números inteiros (int), o resultado também será inteiro (a parte decimal é descartada).\n\nPor exemplo, 7 / 2 entre inteiros resulta em 3. Se quisermos casas decimais, pelo menos um número deve ser double (ex: 7.0 / 2).','int dobro = 6 * 2;\nint metade = 10 / 2;\nSystem.out.println(dobro);','2026-10-08 16:05:50'),(18,4,3,'Operadores Parte 1 - Resto da Divisão (%)','Existe um operador matemático muito útil na programação chamado Módulo, representado pelo símbolo de porcentagem (%).\n\nO operador % NÃO calcula porcentagem! Ele retorna o RESTO de uma divisão inteira.\n\nPor exemplo: na divisão de 10 por 3, o quociente é 3 e sobra 1. Portanto, 10 % 3 resulta em 1!\n\nQuando um número é perfeitamente divisível por outro, o resto é zero (ex: 8 % 2 resulta em 0). É assim que descobrimos se um número é par ou ímpar!','int sobra = 10 % 3;\nint par = 8 % 2;\nSystem.out.println(sobra);','2026-10-08 16:05:50'),(19,4,4,'Operadores Parte 1 - Incremento (++) e Precedência','Somar ou diminuir 1 de uma variável é tão comum em jogos e programas que o Java possui atalhos especiais!\n\nO operador ++ aumenta o valor da variável em 1 unidade (ex: vidas++; é o mesmo que vidas = vidas + 1;).\n\nJá o operador -- diminui o valor da variável em 1 unidade.\n\nAlém disso, assim como na matemática da escola, a multiplicação (*) e a divisão (/) são calculadas ANTES da soma (+) e subtração (-), a menos que usemos parênteses ( )!','int nivel = 1;\nnivel++;\nint pontos = (2 + 3) * 10;\nSystem.out.println(pontos);','2026-10-08 16:05:50'),(20,4,5,'Operadores Parte 1 - Desafio IDE: Calculadora','Chegou a hora de programar sua própria expressão aritmética no editor de código Java!\n\nNeste desafio prático no estilo Codédex, você somará dois números inteiros em uma variável e exibirá o resultado 40 no terminal.\n\nDigite seu código e clique em Executar!','','2026-10-08 16:05:50'),(21,5,1,'Operadores Parte 2 - Maior (>) e Menor (<)','Os operadores relacionais servem para comparar dois valores. O resultado de toda comparação em Java é sempre um boolean: true ou false!\n\nUsamos > para verificar se um valor é maior que outro, e < para verificar se é menor.\n\nTambém temos >= (maior ou igual) e <= (menor ou igual). Por exemplo: 18 >= 18 resulta em true!\n\nEssas comparações são a base para que o programa tome decisões inteligentes.','int idade = 20;\nboolean maiorDeIdade = idade >= 18;\nSystem.out.println(maiorDeIdade);','2026-10-08 16:05:50'),(22,5,2,'Operadores Parte 2 - Igualdade (==) e Diferença (!=)','Preste muita atenção na diferença entre = e == em Java!\n\nUm único sinal de igual (=) serve para ATRIBUIR valor a uma variável (ex: int vidas = 3;).\n\nDois sinais de igual juntos (==) servem para COMPARAR se dois valores são iguais (ex: vidas == 3 resulta em true).\n\nJá o operador != verifica se dois valores são DIFERENTES (ex: 5 != 3 resulta em true, pois 5 é diferente de 3).','int senha = 1234;\nboolean correta = (senha == 1234);\nSystem.out.println(correta);','2026-10-08 16:05:50'),(23,5,3,'Operadores Parte 2 - Operador Lógico E (&&)','Às vezes precisamos testar duas condições ao mesmo tempo. Para isso usamos os operadores lógicos!\n\nO operador && (chamado de AND ou \'E\' lógico) retorna true APENAS se TODAS as condições forem verdadeiras ao mesmo tempo.\n\nPor exemplo: para entrar em um campeonato avançado, o jogador precisa ter (nivel >= 10 && moedas >= 100).\n\nSe uma das condições for false, o resultado inteiro do && será false!','int nivel = 12;\nint moedas = 150;\nboolean podeEntrar = (nivel >= 10) && (moedas >= 100);\nSystem.out.println(podeEntrar);','2026-10-08 16:05:50'),(24,5,4,'Operadores Parte 2 - OU (||) e Negação (!)','O operador || (duas barras verticais, chamado de OR ou \'OU\' lógico) retorna true se PELO MENOS UMA das condições for verdadeira.\n\nPor exemplo: (temIngresso || nomeNaLista) será true mesmo que apenas uma das duas coisas seja verdade!\n\nPor fim, o operador de negação ! (ponto de exclamação) inverte um valor booleano: !true vira false, e !false vira true.','boolean chovendo = false;\nboolean sairDeCasa = !chovendo;\nSystem.out.println(sairDeCasa);','2026-10-08 16:05:50'),(25,5,5,'Operadores Parte 2 - Desafio IDE: Lógica Booleana','Chegou a hora de testar comparações e lógica booleana no editor Java!\n\nNeste desafio prático no estilo Codédex, avalie uma comparação verdadeira (como 10 > 5) e exiba o resultado true no terminal.\n\nEscreva seu código e clique em Executar!','','2026-10-08 16:05:50'),(26,6,1,'Estrutura Condicional Simples: if','O comando \'if\' é a estrutura básica para tomada de decisões em Java.\n\nEle avalia uma condição booleana. Se a expressão for verdadeira (true), o bloco de instruções dentro das chaves será executado.\n\nSe for falsa, o programa simplesmente ignora o bloco e continua a execução normalmente.','public class ExemploIf {\n    public static void main(String[] args) {\n        int idade = 20;\n        if (idade >= 18) {\n            System.out.println(\"Acesso permitido!\");\n        }\n    }\n}','2026-10-08 16:05:50'),(27,6,2,'Estrutura Composta: if e else','Quando precisamos executar um caminho alternativo caso a condição seja falsa, usamos o \'else\'.\n\nO bloco \'else\' nunca recebe uma condição entre parênteses; ele é executado por padrão sempre que o \'if\' falhar.\n\nIsso garante que um dos dois caminhos seja obrigatoriamente seguido pelo programa.','public class ExemploIfElse {\n    public static void main(String[] args) {\n        int saldo = 50;\n        if (saldo >= 100) {\n            System.out.println(\"Compra aprovada!\");\n        } else {\n            System.out.println(\"Saldo insuficiente!\");\n        }\n    }\n}','2026-10-08 16:05:50'),(28,6,3,'Múltiplas Decisões com else if','Quando temos três ou mais condições mutuamente exclusivas, encadeamos instruções com \'else if\'.\n\nO Java testa as condições de cima para baixo. Assim que encontra a primeira condição verdadeira, executa o bloco e encerra a checagem das demais.\n\nO \'else\' no final atua como caso genérico para quando nenhuma condição foi satisfeita.','public class ExemploElseIf {\n    public static void main(String[] args) {\n        int nota = 82;\n        if (nota >= 90) {\n            System.out.println(\"Conceito A\");\n        } else if (nota >= 80) {\n            System.out.println(\"Conceito B\");\n        } else {\n            System.out.println(\"Conceito C\");\n        }\n    }\n}','2026-10-08 16:05:50'),(29,6,4,'Seleção com switch e break','A instrução \'switch\' avalia uma única variável contra valores específicos chamados \'case\'.\n\nÉ uma alternativa muito limpa quando testamos igualdade de inteiros, caracteres ou Strings.\n\nA palavra-chave \'break\' é essencial para encerrar o switch; sem ela, o código continua executando os blocos abaixo (\'fall-through\').','public class ExemploSwitch {\n    public static void main(String[] args) {\n        int dia = 2;\n        switch (dia) {\n            case 1: System.out.println(\"Domingo\"); break;\n            case 2: System.out.println(\"Segunda\"); break;\n            default: System.out.println(\"Outro dia\"); break;\n        }\n    }\n}','2026-10-08 16:05:50'),(30,6,5,'Desafio Prático: Verificador de Decisão','Parabéns por dominar estruturas condicionais! Na programação real, o tempo todo precisamos validar regras de negócio, limites e autorizações.\n\nAgora você aplicará esses conceitos no desafio prático de código a seguir, compilando e testando na IDE!','public class DesafioDecisao {\n    public static void main(String[] args) {\n        int nota = 85;\n        if (nota >= 70) {\n            System.out.println(\"Aprovado\");\n        }\n    }\n}','2026-10-08 16:05:50'),(31,7,1,'Introdução ao System.out: print vs println','Em Java, a saída padrão no terminal é controlada pelo objeto System.out.\n\nO método print() exibe a mensagem na tela sem quebrar linha ao final, permitindo encadear textos na mesma linha.\n\nJá o println() insere automaticamente uma quebra de linha após imprimir o conteúdo, posicionando o cursor na linha seguinte.','public class SaidaBasica {\n    public static void main(String[] args) {\n        System.out.print(\"Carregando\");\n        System.out.print(\"...\");\n        System.out.println(\" Concluído!\");\n    }\n}','2026-10-08 16:05:50'),(32,7,2,'Lendo Dados com Scanner','A classe Scanner (do pacote java.util) é a maneira mais prática de capturar entradas do usuário no teclado.\n\nPara começar, instanciamos: Scanner sc = new Scanner(System.in);\n\nUsamos métodos específicos de acordo com o tipo: nextInt() para inteiros, nextDouble() para números reais e nextLine() para textos completos.','import java.util.Scanner;\n\npublic class Leitura {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int pontuacao = 100;\n        System.out.println(\"Pontos lidos: \" + pontuacao);\n        sc.close();\n    }\n}','2026-10-08 16:05:50'),(33,7,3,'Formatação Precisa com printf','O método printf() permite criar saídas altamente formatadas utilizando marcadores de formato (placeholders).\n\nOs principais marcadores são:\n%s para texto (String)\n%d para números inteiros (decimal integer)\n%.2f para números de ponto flutuante com 2 casas decimais.\n\nIsso evita concatenações confusas de strings com o operador +.','public class ExemploPrintf {\n    public static void main(String[] args) {\n        String item = \"Livro\";\n        double preco = 49.90;\n        System.out.printf(\"Item: %s | Valor: R$ %.2f\\n\", item, preco);\n    }\n}','2026-10-08 16:05:50'),(34,7,4,'Armadilhas de Leitura: Buffer e Quebra de Linha','Um erro comum ao usar Scanner ocorre ao ler um número com nextInt() seguido imediatamente por um nextLine().\n\nO método nextInt() lê apenas o número, deixando a quebra de linha (Enter) pendente no buffer de entrada.\n\nQuando o nextLine() subsequente é chamado, ele consome esse Enter residual e retorna uma String vazia. A solução é adicionar um sc.nextLine() extra para limpar o buffer.','import java.util.Scanner;\n\npublic class LimpezaBuffer {\n    public static void main(String[] args) {\n        // Exemplo ilustrativo de consumo do buffer pendente:\n        int idade = 25;\n        String bufferPendente = \"\\n\"; // Enter pendente consumido\n        String nome = \"Opus\";\n        System.out.println(nome + \" - \" + idade);\n    }\n}','2026-10-08 16:05:50'),(35,7,5,'Desafio Prático: Saída Formatada Profissional','Agora que você domina a saída com printf e manipulação de tipos no console, chegou o momento do desafio prático.\n\nFormate a mensagem exigida na tela com exatidão usando o conhecimento adquirido!','public class DesafioIO {\n    public static void main(String[] args) {\n        String prod = \"Mouse\";\n        double valor = 50.0;\n        System.out.printf(\"%s: R$ %.2f\\n\", prod, valor);\n    }\n}','2026-10-08 16:05:50'),(36,8,1,'Operações Fundamentais e Precedência Matemática','No Java, assim como na matemática tradicional, operadores possuem regras claras de precedência.\n\nMultiplicação (*), divisão (/) e módulo (%) são calculados antes de adição (+) e subtração (-).\n\nPara alterar a ordem natural e forçar a execução prioritária de uma soma ou subtração, usamos parênteses.','public class Precedencia {\n    public static void main(String[] args) {\n        int res1 = 10 + 5 * 2;    // 20\n        int res2 = (10 + 5) * 2;  // 30\n        System.out.println(\"Sem parênteses: \" + res1);\n        System.out.println(\"Com parênteses: \" + res2);\n    }\n}','2026-10-08 16:05:50'),(37,8,2,'Potenciação e Raízes com Math','A classe Math (do pacote padrão java.lang) traz dezenas de funções prontas.\n\nPara calcular potências: Math.pow(base, expoente) retorna um double com o resultado.\n\nPara raiz quadrada: Math.sqrt(numero) retorna a raiz positiva do número informado.','public class FuncoesMath {\n    public static void main(String[] args) {\n        double quad = Math.pow(5, 2); // 25.0\n        double raiz = Math.sqrt(49);   // 7.0\n        System.out.println(\"5 ao quadrado: \" + quad);\n        System.out.println(\"Raiz de 49: \" + raiz);\n    }\n}','2026-10-08 16:05:50'),(38,8,3,'Arredondamentos e Valores Extremos: min, max e round','Outros métodos muito úteis da classe Math incluem:\n\nMath.max(a, b): retorna o maior entre dois números.\nMath.min(a, b): retorna o menor entre dois números.\nMath.abs(x): retorna o valor absoluto (módulo sem sinal).\nMath.round(x): arredonda o valor decimal para o inteiro mais próximo.','public class Arredondamento {\n    public static void main(String[] args) {\n        int maior = Math.max(15, 42); // 42\n        long arredondado = Math.round(7.6); // 8\n        System.out.println(\"Maior: \" + maior + \" | Arredondado: \" + arredondado);\n    }\n}','2026-10-08 16:05:50'),(39,8,4,'Gerando Números Aleatórios com Math.random','O método Math.random() retorna um número decimal aleatório do tipo double no intervalo de 0.0 (inclusivo) até 1.0 (exclusivo).\n\nPara gerar um número inteiro entre 1 e 10, multiplicamos e fazemos o casting:\nint numero = (int)(Math.random() * 10) + 1;\n\nÉ a base para jogos, sorteios e lógicas dinâmicas.','public class Aleatorio {\n    public static void main(String[] args) {\n        double sorteado = Math.random();\n        int dado = (int)(sorteado * 6) + 1; // simula dado de 1 a 6\n        System.out.println(\"Resultado do dado: \" + dado);\n    }\n}','2026-10-08 16:05:50'),(40,8,5,'Desafio Prático: Potência e Cálculos','Você já domina precedência matemática e os recursos da classe Math!\n\nAgora coloque em prática executando o cálculo de potência na IDE do desafio prático.','public class DesafioCalculadora {\n    public static void main(String[] args) {\n        double res = Math.pow(2, 4);\n        System.out.println((int) res);\n    }\n}','2026-10-08 16:05:50'),(41,9,1,'Introdução a Laços','Bem-vindo ao estudo de Laços!\n\nNesta primeira aula, compreenderemos os objetivos principais, a sintaxe necessária e onde esse conceito é aplicado na construção de sistemas corporativos.\n\nA compreensão sólida deste fundamento evitará bugs comuns e tornará seu código muito mais legível.','public class ExemploAula1 {\n    public static void main(String[] args) {\n        System.out.println(\"Iniciando estudos em Laços!\");\n    }\n}','2026-10-08 16:05:50'),(42,9,2,'Fundamentos e Mecânica de Laços','Avançando em Laços, examinamos os mecanismos internos e operadores envolvidos.\n\nJava é uma linguagem com tipagem forte e checagem estática, garantindo que o compilador encontre inconsistências antes mesmo do programa rodar.\n\nPreste sempre atenção aos tipos de retorno e à visibilidade dos recursos.','public class ExemploAula2 {\n    public static void main(String[] args) {\n        // Operação estruturada de Laços\n        int status = 1;\n        System.out.println(\"Status operacional: \" + status);\n    }\n}','2026-10-08 16:05:50'),(43,9,3,'Aplicações Práticas de Laços','Agora que você compreende a base teórica, vamos aplicar Laços em um cenário do dia a dia do desenvolvimento.\n\nSaber combinar condicionais, repetições e tipos de dados permite construir fluxos de negócio consistentes e à prova de falhas.\n\nObserve com atenção como os dados trafegam e são manipulados no exemplo a seguir.','public class ExemploAula3 {\n    public static void main(String[] args) {\n        // Aplicação prática em Laços\n        boolean ativo = true;\n        if (ativo) {\n            System.out.println(\"Processando 1 2 3...\");\n        }\n    }\n}','2026-10-08 16:05:50'),(44,9,4,'Boas Práticas e Prevenção de Falhas em Laços','Programadores profissionais se destacam por antecipar possíveis falhas e aplicar convenções de código limpo (Clean Code).\n\nAo trabalhar com Laços, evite duplicação desnecessária, utilize nomes significativos para variáveis e classes e garanta tratamento adequado para casos excepcionais.\n\nIsso torna seu software robusto e preparado para ambientes de produção.','public class ExemploAula4 {\n    public static void main(String[] args) {\n        // Código padronizado e limpo\n        String resultado = \"1 2 3\";\n        System.out.println(\"Resultado verificado: \" + resultado);\n    }\n}','2026-10-08 16:05:50'),(45,9,5,'Desafio Prático e Consolidação: Laços','Parabéns por completar todas as etapas de estudo de Laços!\n\nAgora é a hora da verdade: você programará no editor integrado, compilará o código em Java e testará se a saída gerada atende exatamente ao requisito da missão.\n\nSucesso no desafio!','public class ExemploAula5 {\n    public static void main(String[] args) {\n        System.out.println(\"1 2 3\");\n    }\n}','2026-10-08 16:05:50'),(46,10,1,'Introdução a Métodos e Funções','Bem-vindo ao estudo de Métodos e Funções!\n\nNesta primeira aula, compreenderemos os objetivos principais, a sintaxe necessária e onde esse conceito é aplicado na construção de sistemas corporativos.\n\nA compreensão sólida deste fundamento evitará bugs