INSERT INTO `perguntas` VALUES (115,1,'Programas de computador usam código para dar instruções às máquinas. Em Java, qual instrução é usada para exibir uma mensagem na tela?','// Como instruir o computador a exibir uma mensagem no terminal?','multipla_escolha','System.out.println','delete','printer.paper','A','2026-10-15 22:33:27'),(116,1,'Qual é a instrução que este código está dando ao computador?','System.out.println(\"Nível 1\");','multipla_escolha','Para exibir o texto \"Nível 1\" na tela','Para enviar o texto para a impressora','Para apagar a palavra do computador','A','2026-10-15 22:33:27'),(117,1,'Complete a instrução Java para enviar uma mensagem para a tela:','___(\"Bem-vindo\");','completar_codigo','System.out.println','send','display','A','2026-10-15 22:33:27'),(118,1,'O que o código abaixo enviará para a tela do computador?','System.out.println(24);','multipla_escolha','O número 24','Nada, pois falta texto','A palavra \"print\"','A','2026-10-15 22:33:27'),(119,1,'Complete a linha de código para exibir a mensagem \"Novo email\":','System.out.println(___);','completar_codigo','\"Novo email\"','Novo email','email.delete','A','2026-10-15 22:33:27'),(120,1,'Verdadeiro ou Falso? O computador executa exatamente as instruções que você escreve no código Java, sem adivinhar o que você pretendia fazer.','// O computador segue cada instrução passo a passo','multipla_escolha','Verdadeiro','Falso','Apenas com conexão à internet','A','2026-10-15 22:33:27'),(121,2,'Em Java, qualquer texto ou frase que queremos imprimir na tela deve estar obrigatoriamente entre qual destes símbolos?','// Delimitação de textos e frases no comando','multipla_escolha','Aspas duplas (\"...\")','Apenas parênteses sem aspas','Cerquilhas (###)','A','2026-10-15 22:33:27'),(122,2,'Complete a instrução abaixo para exibir o texto Level Up na tela:','System.out.println(___);','completar_codigo','\"Level Up\"','Level Up','\'Level Up\'','A','2026-10-15 22:33:27'),(123,2,'O que acontecerá ao tentar executar este código Java sem aspas duplas no texto?','System.out.println(Olá);','multipla_escolha','Ocorrerá um erro de compilação, pois o Java não reconhece palavras sem aspas','O Java exibirá Olá normalmente','O texto será enviado para a lixeira','A','2026-10-15 22:33:27'),(124,2,'Complete o código para um aplicativo de música exibir \"Tocando agora...\":','System.out.println(___);','completar_codigo','\"Tocando agora...\"','Tocando agora...','play_music','A','2026-10-15 22:33:27'),(125,2,'O que o código abaixo enviará para a tela do computador?','System.out.println(\"100\");','multipla_escolha','O texto \"100\" (pois está entre aspas duplas)','Um erro, porque números não aceitam aspas','O número 100 somado a 1','A','2026-10-15 22:33:27'),(126,2,'Verdadeiro ou Falso? Em Java, esquecer de fechar as aspas duplas de um texto gera um erro e impede o programa de compilar.','System.out.println(\"Texto sem fechar aspas);','multipla_escolha','Verdadeiro','Falso','O Java fecha as aspas sozinho','A','2026-10-15 22:33:27'),(127,3,'Java é uma linguagem Case-Sensitive. O que isso significa na prática?','// Case-Sensitive','multipla_escolha','O Java diferencia letras maiúsculas de minúsculas','O Java aceita qualquer letra maiúscula ou minúscula sem distinção','O Java só aceita comandos em maiúsculas','A','2026-10-15 22:33:27'),(128,3,'Complete a instrução com o nome correto da classe:','___.out.println(\"Opus\");','completar_codigo','System','system','SYSTEM','A','2026-10-15 22:33:27'),(129,3,'Complete a instrução com o método de exibição de texto:','System.out.___(\"Aprendendo Java\");','completar_codigo','println','Println','PRINTLN','A','2026-10-15 22:33:27'),(130,3,'Qual destas linhas de código Java está escrita com as maiúsculas e minúsculas corretas?','// Qual opção compila corretamente em Java?','multipla_escolha','System.out.println(\"Código correto!\");','system.out.println(\"Código correto!\");','SYSTEM.OUT.PRINTLN(\"Código correto!\");','A','2026-10-15 22:33:27'),(131,3,'Complete a chamada de impressão:','System.___.println(\"Atenção aos detalhes!\");','completar_codigo','out','Out','OUT','A','2026-10-15 22:33:27'),(132,3,'Verdadeiro ou Falso? Se você escrever \"system.out.println()\" com \'s\' minúsculo, o compilador Java não reconhecerá o comando.','system.out.println(\"Teste\");','multipla_escolha','Verdadeiro','Falso','O Java converte para maiúsculo sozinho','A','2026-10-15 22:33:27'),(133,4,'Toda declaração ou instrução de comando em Java deve terminar obrigatoriamente com qual símbolo de pontuação?','// Pontuação obrigatória ao final do comando','multipla_escolha','Ponto e vírgula (;)','Dois pontos (:)','Ponto final (.)','A','2026-10-15 22:33:27'),(134,4,'Complete o encerramento da instrução Java:','System.out.println(\"Quase lá\")___','completar_codigo',';',':','.','A','2026-10-15 22:33:27'),(135,4,'Complete o fechamento da instrução:','System.out.println(\"Vitória!\"___','completar_codigo',');',':)','.;','A','2026-10-15 22:33:27'),(136,4,'O código em programas de computador é feito de declarações. Qual é o número de declarações neste código Java?','System.out.println(\"Harry Potter\");\nSystem.out.println(\"J. K. Rowling\");','multipla_escolha','2','1','3','A','2026-10-15 22:33:27'),(137,4,'Complete com o comando completo para exibir a mensagem na tela:','___(\"Código Limpo\");','completar_codigo','System.out.println','System.out.print_line','print','A','2026-10-15 22:33:27'),(138,4,'Qual destas opções de código Java está 100% correta de acordo com todas as regras de sintaxe aprendidas?','// Qual declaração segue todas as regras de sintaxe do Java?','multipla_escolha','System.out.println(\"Parabéns!\");','System.out.println(\"Parabéns!\")','system.out.println(Parabéns!);','A','2026-10-15 22:33:27'),(163,6,'O que é uma variável na programação Java?','// Conceito fundamental de programação','multipla_escolha','Um espaço na memória com nome usado para armazenar dados','Um comando que desliga o terminal do computador','Um arquivo que só pode ser aberto através da internet','A','2026-10-15 22:51:44'),(164,6,'Qual tipo primitivo em Java é utilizado para armazenar números inteiros?','// 10, 20, 30...','multipla_escolha','int','text','number_full','A','2026-10-15 22:51:44'),(165,6,'Complete a instrução para declarar a variável inteira:','___ vidas = 3;','completar_codigo','int','integer','INT','A','2026-10-15 22:51:44'),(166,6,'O que o código abaixo enviará para o terminal do computador?','int nivel = 5;\nSystem.out.println(nivel);','multipla_escolha','5','\"nivel\"','Um erro de compilação','A','2026-10-15 22:51:44'),(167,6,'Qual é a diferença entre System.out.println(idade); e System.out.println(\"idade\");?','// Com aspas vs sem aspas','multipla_escolha','Sem aspas imprime o valor da variável; com aspas imprime o texto literal \"idade\"','Não existe diferença alguma na saída do programa','Sem aspas causa um erro obrigatório no compilador','A','2026-10-15 22:51:44'),(168,6,'Complete a instrução para exibir o valor armazenado na variável moedas:','int moedas = 50;\nSystem.out.println(___);','completar_codigo','moedas','\"moedas\"','50 = moedas','A','2026-10-15 22:51:44'),(169,7,'Qual tipo de dado em Java é utilizado para armazenar palavras e frases?','// Ex: \"Olá, Jogador!\"','multipla_escolha','String','str','text','A','2026-10-15 22:51:44'),(170,7,'Complete com o tipo de dado para criar a variável de texto:','___ cargo = \"Desenvolvedor\";','completar_codigo','String','string','STRING','A','2026-10-15 22:51:44'),(171,7,'Qual declaração de variável de texto segue as regras da linguagem Java?','// Declaração de texto','multipla_escolha','String cidade = \"Curitiba\";','String cidade = Curitiba;','string cidade = \"Curitiba\";','A','2026-10-15 22:51:44'),(172,7,'Complete o valor da variável para armazenar o nome Opus:','String app = ___;','completar_codigo','\"Opus\"','Opus','(Opus)','A','2026-10-15 22:51:44'),(173,7,'O que acontecerá ao tentar compilar este código Java?','String animal = Gato;','multipla_escolha','Ocorrerá um erro de compilação por falta de aspas duplas no texto','O Java colocará as aspas duplas automaticamente','A palavra será convertida para número','A','2026-10-15 22:51:45'),(174,7,'Verdadeiro ou Falso? O nome do tipo String em Java deve iniciar obrigatoriamente com letra maiúscula.','String nick = \"Player1\";','multipla_escolha','Verdadeiro','Falso','Apenas em programas para web','A','2026-10-15 22:51:45'),(175,8,'Em Java, quando usamos o operador + envolvendo um texto, qual operação é realizada?','\"Pontos: \" + 50','multipla_escolha','Concatenação (junção de textos)','Soma matemática dos caracteres','Divisão de strings','A','2026-10-15 22:51:45'),(176,8,'Qual será a saída exibida no terminal após executar este código?','String jogo = \"Xadrez\";\nSystem.out.println(\"Partida de \" + jogo);','multipla_escolha','Partida de Xadrez','Partida de jogo','\"Partida de Xadrez\"','A','2026-10-15 22:51:45'),(177,8,'Complete a instrução para juntar a saudação com o nome da variável:','String nick = \"Alex\";\nSystem.out.println(\"Olá, \" ___ nick);','completar_codigo','+','&','.','A','2026-10-15 22:51:45'),(178,8,'Qual será o resultado exato da impressão abaixo?','String cor = \"Azul\";\nSystem.out.println(\"Cor:\" + cor);','multipla_escolha','Cor:Azul','Cor: Azul','Cor Azul','A','2026-10-15 22:51:45'),(179,8,'Complete com a variável para exibir \"Nível 10\" no terminal:','int level = 10;\nSystem.out.println(\"Nível \" + ___);','completar_codigo','level','\"level\"','10','A','2026-10-15 22:51:45'),(180,8,'O que será exibido no terminal ao executar este comando?','int a = 1;\nint b = 2;\nSystem.out.println(\"Total: \" + a + b);','multipla_escolha','Total: 12','Total: 3','Total: a + b','A','2026-10-15 22:51:45'),(181,9,'Para atualizar o valor de uma variável já criada anteriormente, como devemos proceder?','// Atualização de variável','multipla_escolha','Escrever apenas o nome da variável e o novo valor, sem repetir o tipo','Repetir obriga